-- Generated by scripts/build_compiled.py from src/fraudrules/rules/first-party/fp-003-payment-stacking.yaml. Do not edit.
-- FP-003 Several card payments in a few days adding up to more than the limit
SELECT
  'FP-003' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 432000
WHERE
  (
    a.account_type = 'card'
    AND a.txn_type = 'payment'
    AND a.direction = 'in'
    AND a.credit_limit_cents > 0
  )
  AND (
    b.account_type = 'card' AND b.txn_type = 'payment' AND b.direction = 'in'
  )
GROUP BY
  a.id
HAVING
  (
    COUNT(*) >= 3 AND SUM(b.amount_cents) * 100 >= MAX(a.credit_limit_cents) * 100
  );
